//! Generates the desktop session's announcement ids from their own
//! definitions, so a guest kernel links none of the desktop.

use std::env;
use std::fs;
use std::path::PathBuf;

use tairix_desktop_session::{MENU_SHOWN, WINDOW_SHOWN};

fn main() {
    let out_dir = env::var_os("OUT_DIR").expect("OUT_DIR set by cargo");
    let ids = format!(
        "// Auto-generated by build.rs. DO NOT EDIT.\n\
         /// The desktop's record of a served window's first frame on screen.\n\
         pub const WINDOW_SHOWN: u32 = {shown};\n\
         /// The desktop's record of a menu chain's plates on screen.\n\
         pub const MENU_SHOWN: u32 = {menu};\n",
        shown = WINDOW_SHOWN.0,
        menu = MENU_SHOWN.0,
    );
    fs::write(PathBuf::from(out_dir).join("announcements.rs"), ids)
        .expect("write announcements.rs");
}
